// Real Win32 resource/SDK seam test. The fixture contains only generated bytes.
#include "cstdmf/cstdmf_windows.hpp"
#include "cstdmf/allocator.hpp"
#include "cstdmf/log_msg.hpp"
#include "resmgr/bwresource.hpp"
#include "resmgr/multi_file_system.hpp"
#include "stock_audio_io.hpp"

#include <AK/AkWwiseSDKVersion.h>
#include <AK/SoundEngine/Common/AkMemoryMgr.h>
#include <AK/SoundEngine/Common/AkModule.h>
#include <AK/SoundEngine/Common/IAkStreamMgr.h>

#include <array>
#include <atomic>
#include <cstdlib>
#include <exception>
#include <iostream>
#include <memory>
#include <stdexcept>
#include <thread>

#if AK_WWISESDK_VERSION_MAJOR != 2017 || AK_WWISESDK_VERSION_MINOR != 1 || \
    AK_WWISESDK_VERSION_SUBMINOR != 9 || AK_WWISESDK_VERSION_BUILD != 6501
#error This probe requires the reviewed Wwise 2017.1.9.6501 SDK.
#endif

namespace AK {
void* AllocHook(size_t size) { return std::malloc(size); }
void FreeHook(void* memory) { std::free(memory); }
void* VirtualAllocHook(void* address, size_t size, DWORD allocation, DWORD protection) {
    return ::VirtualAlloc(address, size, allocation, protection);
}
void VirtualFreeHook(void* address, size_t size, DWORD release) {
    ::VirtualFree(address, size, release);
}
}

namespace {
const AkUInt32 resourceSize = 4096;

void require(bool accepted, const char* message) {
    if (!accepted) throw std::runtime_error(message);
}
void success(AKRESULT result, const char* operation) {
    if (result != AK_Success) {
        std::cerr << operation << " result=" << int(result) << std::endl;
        throw std::runtime_error(operation);
    }
}
void checkBytes(const unsigned char* bytes, AkUInt32 offset, AkUInt32 count,
    unsigned multiplier, unsigned increment) {
    for (AkUInt32 index = 0; index < count; ++index)
        require(bytes[index] == static_cast<unsigned char>(
            (offset + index) * multiplier + increment), "Resource bytes differ");
}

class ProbeIO : public BW::StockAudioResourceIO {
public:
    std::atomic<unsigned> reads{0};
    AKRESULT Read(AkFileDesc& file, const AkIoHeuristics& heuristics,
        void* output, AkIOTransferInfo& transfer) override {
        ++reads;
        return StockAudioResourceIO::Read(file, heuristics, output, transfer);
    }
};

// Cleanup uses the same ownership order as the application, without SoundEngine.
struct Session {
    bool memoryReady = false;
    std::unique_ptr<ProbeIO> io;
    ~Session() {
        if (AK::IAkStreamMgr::Get()) {
            if (io) { io->Term(); io.reset(); }
            AK::IAkStreamMgr::Get()->Destroy();
        }
        if (memoryReady) AK::MemoryMgr::Term();
    }
    void init() {
        std::cout << "Initializing real Wwise stream manager and mounted resource IO" << std::endl;
        AkMemSettings memory = {};
        memory.uMaxNumPools = 20;
        success(AK::MemoryMgr::Init(&memory), "MemoryMgr::Init");
        memoryReady = true;
        AkStreamMgrSettings manager;
        AK::StreamMgr::GetDefaultSettings(manager);
        require(AK::StreamMgr::Create(manager) != NULL, "StreamMgr::Create failed");
        AkDeviceSettings device;
        AK::StreamMgr::GetDefaultDeviceSettings(device);
        io.reset(new ProbeIO);
        success(io->Init(device), "StockAudioResourceIO::Init");
        success(io->setResourcePath("audioww"), "setResourcePath");
    }
};

struct Resource {
    ProbeIO& io;
    AkFileDesc descriptor = {};
    bool opened = false;
    explicit Resource(ProbeIO& owner) : io(owner) {}
    ~Resource() { close(); }
    void open(const AkOSChar* name) {
        require(!opened, "Resource was already open");
        bool synchronous = true;
        success(io.Open(name, AK_OpenModeRead, NULL, synchronous, descriptor), "IO::Open");
        opened = true;
        require(synchronous && descriptor.iFileSize == static_cast<AkInt64>(resourceSize),
            "Unexpected resource descriptor");
    }
    void close() {
        if (opened) {
            io.Close(descriptor);
            opened = false;
        }
    }
    void read(AkUInt32 offset, unsigned multiplier, unsigned increment) {
        std::array<unsigned char, 257> bytes;
        AkIOTransferInfo transfer = {};
        transfer.uFilePosition = offset;
        transfer.uBufferSize = static_cast<AkUInt32>(bytes.size());
        transfer.uRequestedSize = static_cast<AkUInt32>(bytes.size());
        AkIoHeuristics heuristics = {};
        success(io.Read(descriptor, heuristics, bytes.data(), transfer), "IO::Read");
        checkBytes(bytes.data(), offset, transfer.uRequestedSize, multiplier, increment);
    }
};

template<class Main, class Worker> void concurrently(Main main, Worker worker) {
    std::exception_ptr mainError, workerError;
    std::thread thread([&] {
        try { worker(); } catch (...) { workerError = std::current_exception(); }
    });
    try { main(); } catch (...) { mainError = std::current_exception(); }
    thread.join();
    if (mainError) std::rethrow_exception(mainError);
    if (workerError) std::rethrow_exception(workerError);
}

struct StandardStream {
    AK::IAkStdStream* stream = NULL;
    ~StandardStream() { close(); }
    void close() {
        if (stream) { stream->Destroy(); stream = NULL; }
    }
    void open(const AkOSChar* name) {
        require(!stream, "Standard stream was already open");
        success(AK::IAkStreamMgr::Get()->CreateStd(name, NULL,
            AK_OpenModeRead, stream, true), "StreamMgr::CreateStd");
    }
    void read(AkUInt32 offset, unsigned multiplier, unsigned increment) {
        std::array<unsigned char, 513> bytes;
        AkInt64 position = -1;
        success(stream->SetPosition(offset, AK_MoveBegin, &position), "Stream::SetPosition");
        require(position == static_cast<AkInt64>(offset), "Standard stream seek differs");
        AkUInt32 received = 0;
        success(stream->Read(bytes.data(), static_cast<AkUInt32>(bytes.size()),
            true, AK_DEFAULT_PRIORITY, 1000.f, received), "Stream::Read");
        require(received == bytes.size(), "Standard stream returned a short read");
        checkBytes(bytes.data(), offset, received, multiplier, increment);
    }
};

void exercise() {
    Session session;
    session.init();
    ProbeIO& io = *session.io;
    {
        Resource first(io), second(io);
        first.open(AKTEXT("first.bin"));
        // The old adapter retains the same ZIP mutex after the first Open.
        std::cout << "Opening second resource while first remains open" << std::endl;
        second.open(AKTEXT("second.bin"));
        concurrently([&] {
            for (AkUInt32 index = 0; index < 32; ++index)
                first.read(index * 19, 17, 3);
        }, [&] {
            for (AkUInt32 index = 0; index < 32; ++index) {
                first.read(index * 23, 17, 3);
                second.read(index * 31, 29, 11);
            }
        });
        // A ZIP stream also transfers the archive lock's ownership on Close.
        concurrently([] {}, [&] { first.close(); });
        first.open(AKTEXT("first.bin"));
        second.read(3, 29, 11);
        first.read(5, 17, 3);
    }
    std::cout << "Overlapping handles, concurrent reads, cross-thread close/reopen passed" << std::endl;
    const unsigned previousReads = io.reads.load();
    {
        StandardStream first, second;
        first.open(AKTEXT("first.bin"));
        second.open(AKTEXT("second.bin"));
        // Each SDK stream has one caller; actual low-level reads use its device.
        concurrently([&] {
            for (AkUInt32 index = 0; index < 8; ++index)
                first.read(index * 47, 17, 3);
        }, [&] {
            for (AkUInt32 index = 0; index < 8; ++index)
                second.read(index * 53, 29, 11);
        });
        first.close();
        first.open(AKTEXT("first.bin"));
        first.read(1, 17, 3);
        second.read(2, 29, 11);
    }
    require(io.reads.load() > previousReads, "SDK bypassed the actual resource IO");
    std::cout << "Real SDK standard streams and low-level resource reads passed" << std::endl;
    io.Term();
    io.Term();
    require(AK::StreamMgr::GetFileLocationResolver() == NULL, "Resolver survived IO teardown");
    std::cout << "Repeated IO teardown passed" << std::endl;
}
}

int main(int argc, char** argv) {
    BW_SYSTEMSTAGE_MAIN();
    ::SetEnvironmentVariableA("BW_UNATTENDED_MACHINE", "TRUE");
    ::SetErrorMode(SEM_FAILCRITICALERRORS | SEM_NOGPFAULTERRORBOX);
    BW::LogMsg::automatedTest(true);
    if (argc < 2) {
        std::cerr << "Usage: probe_stock_audio_resources <generated.pkg> [-unattended]" << std::endl;
        return 2;
    }
    int outcome = 1;
    try {
        BW::vector<BW::string> paths;
        paths.push_back(argv[1]);
        require(BW::BWResource::init(paths), "BWResource::init failed");
        BW::IFileSystem::FileDataLocation first, second;
        BW::MultiFileSystem* files = BW::BWResource::instance().fileSystem();
        require(files->locateFileData("audioww/first.bin", &first) &&
            files->locateFileData("audioww/second.bin", &second), "Cannot locate stored fixture resources");
        require(first.hostResourceID == second.hostResourceID && first.offset > 0 &&
            second.offset > 0 && first.offset != second.offset,
            "Fixture resources must share one archive and have different offsets");
        for (unsigned iteration = 0; iteration < 2; ++iteration) {
            exercise();
            std::cout << "Mounted resource/SDK lifetime cycle " << iteration + 1 << " passed" << std::endl;
        }
        outcome = 0;
    } catch (const std::exception& error) {
        std::cerr << "Mounted resource/SDK probe failed: " << error.what() << std::endl;
    }
    BW::BWResource::fini();
    BW::LogMsg::fini();
    return outcome;
}
